INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15944, 'FDA Notices Issued Over Vimal Elaichi Advertisement', 'विमल इलायची विज्ञापन पर FDA ने जारी किए नोटिस', 'Maharashtra''s Food and Drug Administration (FDA) has issued notices to actors Shah Rukh Khan, Ajay Devgn, and Tiger Shroff regarding an advertisement for Vimal Elaichi. The FDA has warned the actors over their endorsement of the product. Actor Mukesh Khanna has supported the FDA''s action, stating the actors should apologize.', 'महाराष्ट्र के खाद्य एवं औषधि प्रशासन (FDA) ने विमल इलायची के विज्ञापन को लेकर अभिनेता शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए हैं। FDA ने उत्पाद के प्रचार को लेकर अभिनेताओं को चेतावनी दी है। अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया है और कहा है कि अभिनेताओं को माफी मांगनी चाहिए।', '["Maharashtra FDA issued notices to Shah Rukh Khan, Ajay Devgn, and Tiger Shroff.", "The notices concern an advertisement for Vimal Elaichi.", "The FDA has issued a warning to the actors.", "Actor Mukesh Khanna backed the FDA''s action and called for an apology."]'::jsonb, '["महाराष्ट्र FDA ने शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए।", "नोटिस विमल इलायची के विज्ञापन से संबंधित हैं।", "FDA ने अभिनेताओं को चेतावनी जारी की है।", "अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया और माफी की मांग की।"]'::jsonb, 'Crime & Law', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["The Indian Express"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Punjab Kesari"], "owners": ["Punjab Kesari"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Punjab Kesari", "owner": "Punjab Kesari", "lean": "right", "language": "hi", "url": "https://www.punjabkesari.in/national/news/maharashtra-fda-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-elaichi-2369931", "headline": "शाहरुख - अजय - टाइगर की बढ़ी मुश्किलें , विमल इलायची विज्ञापन पर महाराष्ट्र FDA का नोटिस , जारी की चेतावनी - maharashtra fda shah rukh khan ajay devgn tiger shroff vimal elaichi"}, {"source": "The Indian Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://indianexpress.com/article/entertainment/bollywood/mukesh-khanna-fda-notices-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-ad-apologise-10838375", "headline": "Mukesh Khanna backs FDA notices to Shah Rukh, Ajay, Tiger over Vimal ad: ‘Apologise’"}]'::jsonb, '{"title": "FDA Notices Issued Over Vimal Elaichi Advertisement", "summary": "Maharashtra''s Food and Drug Administration (FDA) has issued notices to actors Shah Rukh Khan, Ajay Devgn, and Tiger Shroff regarding an advertisement for Vimal Elaichi. The FDA has warned the actors over their endorsement of the product. Actor Mukesh Khanna has supported the FDA''s action, stating the actors should apologize.", "summary_points": ["Maharashtra FDA issued notices to Shah Rukh Khan, Ajay Devgn, and Tiger Shroff.", "The notices concern an advertisement for Vimal Elaichi.", "The FDA has issued a warning to the actors.", "Actor Mukesh Khanna backed the FDA''s action and called for an apology."], "title_hi": "विमल इलायची विज्ञापन पर FDA ने जारी किए नोटिस", "summary_hi": "महाराष्ट्र के खाद्य एवं औषधि प्रशासन (FDA) ने विमल इलायची के विज्ञापन को लेकर अभिनेता शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए हैं। FDA ने उत्पाद के प्रचार को लेकर अभिनेताओं को चेतावनी दी है। अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया है और कहा है कि अभिनेताओं को माफी मांगनी चाहिए।", "summary_points_hi": ["महाराष्ट्र FDA ने शाहरुख खान, अजय देवगन और टाइगर श्रॉफ को नोटिस जारी किए।", "नोटिस विमल इलायची के विज्ञापन से संबंधित हैं।", "FDA ने अभिनेताओं को चेतावनी जारी की है।", "अभिनेता मुकेश खन्ना ने FDA की कार्रवाई का समर्थन किया और माफी की मांग की।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "https://img.punjabkesari.in/multimedia/914/0/0X0/0/static.punjabkesari.in/2026_8image_10_19_195030100vimalelaichi.jpg", "sources": [{"source": "Punjab Kesari", "owner": "Punjab Kesari", "lean": "right", "language": "hi", "url": "https://www.punjabkesari.in/national/news/maharashtra-fda-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-elaichi-2369931", "headline": "शाहरुख - अजय - टाइगर की बढ़ी मुश्किलें , विमल इलायची विज्ञापन पर महाराष्ट्र FDA का नोटिस , जारी की चेतावनी - maharashtra fda shah rukh khan ajay devgn tiger shroff vimal elaichi"}, {"source": "The Indian Express", "owner": "Indian Express Group", "lean": "center", "language": "en", "url": "https://indianexpress.com/article/entertainment/bollywood/mukesh-khanna-fda-notices-shah-rukh-khan-ajay-devgn-tiger-shroff-vimal-ad-apologise-10838375", "headline": "Mukesh Khanna backs FDA notices to Shah Rukh, Ajay, Tiger over Vimal ad: ‘Apologise’"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["The Indian Express"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Punjab Kesari"], "owners": ["Punjab Kesari"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://img.punjabkesari.in/multimedia/914/0/0X0/0/static.punjabkesari.in/2026_8image_10_19_195030100vimalelaichi.jpg', FALSE, FALSE, 'llm', 'sl-14913', NULL, '2026-08-18T10:30:17.802783'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15943, 'Young professional quits high-paying job for fashion tech startup', 'युवती ने फैशन-टेक स्टार्टअप के लिए छोड़ी मोटी तनख्वाह वाली नौकरी', 'A 23-year-old woman resigned from her position at Morgan Stanley after four months, citing a desire for a different life path. She has chosen to pursue her ambition of starting a fashion-tech company. The decision was reportedly influenced by a desire to avoid a specific lifestyle and was aided by a cold email strategy. She was earning approximately ₹94 lakh annually.', '23 वर्षीय एक महिला ने एक अलग जीवन पथ की इच्छा का हवाला देते हुए चार महीने बाद मॉर्गन स्टेनली में अपने पद से इस्तीफा दे दिया। उसने फैशन-टेक कंपनी शुरू करने की अपनी महत्वाकांक्षा को पूरा करने का विकल्प चुना है। यह निर्णय कथित तौर पर एक विशिष्ट जीवन शैली से बचने की इच्छा से प्रभावित था और कोल्ड ईमेल रणनीति द्वारा सहायता प्राप्त की गई थी। वह सालाना लगभग ₹94 लाख कमा रही थी।', '["A 23-year-old individual resigned from Morgan Stanley after four months.", "The individual cited a desire for a different life and to avoid a particular lifestyle.", "The former employee plans to start a fashion-tech startup.", "A cold email strategy reportedly assisted in her new venture.", "Her previous annual salary was approximately ₹94 lakh."]'::jsonb, '["23 वर्षीय एक व्यक्ति ने चार महीने बाद मॉर्गन स्टेनली से इस्तीफा दे दिया।", "व्यक्ति ने एक अलग जीवन की इच्छा और एक विशेष जीवन शैली से बचने की इच्छा का हवाला दिया।", "पूर्व कर्मचारी एक फैशन-टेक स्टार्टअप शुरू करने की योजना बना रही है।", "कथित तौर पर एक कोल्ड ईमेल रणनीति ने उसके नए उद्यम में सहायता की।", "उसका पिछला वार्षिक वेतन लगभग ₹94 लाख था।"]'::jsonb, 'Society', 'India', 0, 1, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Hindustan Times", "Mint"], "owners": ["HT Media"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Hindustan Times", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "‘I didn’t want that life’: 23-year-old quits ₹94 lakh Morgan Stanley job after 4 months for fashion tech | Trending"}, {"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/news/us-news/23yearold-quits-morgan-stanley-to-start-fashion-tech-startup-reveals-how-cold-email-strategy-helped-her-11787045669047.html", "headline": "23-year-old quits Morgan Stanley to start fashion-tech startup, reveals how cold email strategy helped her"}]'::jsonb, '{"title": "Young professional quits high-paying job for fashion tech startup", "summary": "A 23-year-old woman resigned from her position at Morgan Stanley after four months, citing a desire for a different life path. She has chosen to pursue her ambition of starting a fashion-tech company. The decision was reportedly influenced by a desire to avoid a specific lifestyle and was aided by a cold email strategy. She was earning approximately ₹94 lakh annually.", "summary_points": ["A 23-year-old individual resigned from Morgan Stanley after four months.", "The individual cited a desire for a different life and to avoid a particular lifestyle.", "The former employee plans to start a fashion-tech startup.", "A cold email strategy reportedly assisted in her new venture.", "Her previous annual salary was approximately ₹94 lakh."], "title_hi": "युवती ने फैशन-टेक स्टार्टअप के लिए छोड़ी मोटी तनख्वाह वाली नौकरी", "summary_hi": "23 वर्षीय एक महिला ने एक अलग जीवन पथ की इच्छा का हवाला देते हुए चार महीने बाद मॉर्गन स्टेनली में अपने पद से इस्तीफा दे दिया। उसने फैशन-टेक कंपनी शुरू करने की अपनी महत्वाकांक्षा को पूरा करने का विकल्प चुना है। यह निर्णय कथित तौर पर एक विशिष्ट जीवन शैली से बचने की इच्छा से प्रभावित था और कोल्ड ईमेल रणनीति द्वारा सहायता प्राप्त की गई थी। वह सालाना लगभग ₹94 लाख कमा रही थी।", "summary_points_hi": ["23 वर्षीय एक व्यक्ति ने चार महीने बाद मॉर्गन स्टेनली से इस्तीफा दे दिया।", "व्यक्ति ने एक अलग जीवन की इच्छा और एक विशेष जीवन शैली से बचने की इच्छा का हवाला दिया।", "पूर्व कर्मचारी एक फैशन-टेक स्टार्टअप शुरू करने की योजना बना रही है।", "कथित तौर पर एक कोल्ड ईमेल रणनीति ने उसके नए उद्यम में सहायता की।", "उसका पिछला वार्षिक वेतन लगभग ₹94 लाख था।"], "framing": {}, "framing_hi": {}, "topic": "Society", "region": "India", "published_at": null, "image_url": "https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/pexels-photo-7429474_1787045779156_1787045801259_0f2e75bb-da47-4708-a198-e4895f918373.jpeg", "sources": [{"source": "Hindustan Times", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "‘I didn’t want that life’: 23-year-old quits ₹94 lakh Morgan Stanley job after 4 months for fashion tech | Trending"}, {"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/news/us-news/23yearold-quits-morgan-stanley-to-start-fashion-tech-startup-reveals-how-cold-email-strategy-helped-her-11787045669047.html", "headline": "23-year-old quits Morgan Stanley to start fashion-tech startup, reveals how cold email strategy helped her"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Hindustan Times", "Mint"], "owners": ["HT Media"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/pexels-photo-7429474_1787045779156_1787045801259_0f2e75bb-da47-4708-a198-e4895f918373.jpeg', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.781024'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15942, 'Four IPOs Open for Subscription Amidst Varying Investor Interest', 'चार आईपीओ सब्सक्रिप्शन के लिए खुले, निवेशकों की रुचि में भिन्नता', 'Four initial public offerings (IPOs) opened for subscription, indicating diverse investor engagement. Sunshine Pictures and Lalithaa Jewellery Mart are experiencing higher demand. In contrast, Shankesh Jewellers and Horizon Industrial Parks are seeing more subdued responses as the bidding process continues. The grey market premium (GMP) for these IPOs is being closely watched for further indications of investor sentiment.', 'चार आरंभिक सार्वजनिक पेशकश (आईपीओ) सब्सक्रिप्शन के लिए खुले, जो विविध निवेशक जुड़ाव का संकेत देते हैं। सनशाइन पिक्चर्स और ललिथा ज्वेलरी मार्ट उच्च मांग का अनुभव कर रहे हैं। इसके विपरीत, शंकेश ज्वेलर्स और होराइजन इंडस्ट्रियल पार्क्स बोली प्रक्रिया जारी रहने के साथ अधिक शांत प्रतिक्रियाएं देख रहे हैं। इन आईपीओ के लिए ग्रे मार्केट प्रीमियम (जीएमपी) को निवेशक भावना के आगे के संकेतों के लिए बारीकी से देखा जा रहा है।', '["Four IPOs are currently open for subscription.", "Sunshine Pictures and Lalithaa Jewellery Mart are attracting significant investor interest.", "Shankesh Jewellers and Horizon Industrial Parks are experiencing less demand.", "Grey market premiums are being monitored for investor sentiment indicators."]'::jsonb, '["चार आईपीओ वर्तमान में सब्सक्रिप्शन के लिए खुले हैं।", "सनशाइन पिक्चर्स और ललिथा ज्वेलरी मार्ट महत्वपूर्ण निवेशक रुचि आकर्षित कर रहे हैं।", "शंकेश ज्वेलर्स और होराइजन इंडस्ट्रियल पार्क्स कम मांग का अनुभव कर रहे हैं।", "निवेशक भावना संकेतकों के लिए ग्रे मार्केट प्रीमियम की निगरानी की जा रही है।"]'::jsonb, 'Economy', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Business Standard", "Mint"], "owners": ["Business Standard", "HT Media"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Reports focus on the opening of four IPOs for subscription.", "Highlights varying levels of investor interest, with some IPOs seeing higher demand than others.", "Mentions specific companies like Sunshine Pictures, Lalithaa Jewellery Mart, Shankesh Jewellers, and Horizon Industrial Parks.", "Notes the observation of grey market premiums (GMP) as an indicator of investor sentiment."]}'::jsonb, '{"center": ["रिपोर्टें सब्सक्रिप्शन के लिए चार आईपीओ के खुलने पर केंद्रित हैं।", "कुछ आईपीओ की मांग दूसरों की तुलना में अधिक होने के साथ, निवेशकों की रुचि के विभिन्न स्तरों पर प्रकाश डालता है।", "सनशाइन पिक्चर्स, ललिथा ज्वेलरी मार्ट, शंकेश ज्वेलर्स और होराइजन इंडस्ट्रियल पार्क्स जैसी विशिष्ट कंपनियों का उल्लेख करता है।", "निवेशक भावना के संकेतक के रूप में ग्रे मार्केट प्रीमियम (जीएमपी) के अवलोकन को नोट करता है।"]}'::jsonb, '[{"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "en", "url": "https://www.business-standard.com/markets/ipo/shankesh-jewellers-ipo-gmp-at-2-offer-opens-today-can-it-add-shine-to-your-portfolio-126081800143_1.html", "headline": "Shankesh Jewellers IPO opens today : Can it add shine to your portfolio ?"}, {"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/market/ipo/ipo-gmps-lalitha-jewellery-ipo-gmp-vs-horizon-industrial-parks-ipo-gmp-vs-sunshine-pictures-ipo-gmp-11787036925581.html", "headline": "IPO GMPs: Lalitha Jewellery IPO, Horizon Industrial Parks IPO to Shankesh Jewellers IPO —what grey market premium hints"}]'::jsonb, '{"title": "Four IPOs Open for Subscription Amidst Varying Investor Interest", "summary": "Four initial public offerings (IPOs) opened for subscription, indicating diverse investor engagement. Sunshine Pictures and Lalithaa Jewellery Mart are experiencing higher demand. In contrast, Shankesh Jewellers and Horizon Industrial Parks are seeing more subdued responses as the bidding process continues. The grey market premium (GMP) for these IPOs is being closely watched for further indications of investor sentiment.", "summary_points": ["Four IPOs are currently open for subscription.", "Sunshine Pictures and Lalithaa Jewellery Mart are attracting significant investor interest.", "Shankesh Jewellers and Horizon Industrial Parks are experiencing less demand.", "Grey market premiums are being monitored for investor sentiment indicators."], "title_hi": "चार आईपीओ सब्सक्रिप्शन के लिए खुले, निवेशकों की रुचि में भिन्नता", "summary_hi": "चार आरंभिक सार्वजनिक पेशकश (आईपीओ) सब्सक्रिप्शन के लिए खुले, जो विविध निवेशक जुड़ाव का संकेत देते हैं। सनशाइन पिक्चर्स और ललिथा ज्वेलरी मार्ट उच्च मांग का अनुभव कर रहे हैं। इसके विपरीत, शंकेश ज्वेलर्स और होराइजन इंडस्ट्रियल पार्क्स बोली प्रक्रिया जारी रहने के साथ अधिक शांत प्रतिक्रियाएं देख रहे हैं। इन आईपीओ के लिए ग्रे मार्केट प्रीमियम (जीएमपी) को निवेशक भावना के आगे के संकेतों के लिए बारीकी से देखा जा रहा है।", "summary_points_hi": ["चार आईपीओ वर्तमान में सब्सक्रिप्शन के लिए खुले हैं।", "सनशाइन पिक्चर्स और ललिथा ज्वेलरी मार्ट महत्वपूर्ण निवेशक रुचि आकर्षित कर रहे हैं।", "शंकेश ज्वेलर्स और होराइजन इंडस्ट्रियल पार्क्स कम मांग का अनुभव कर रहे हैं।", "निवेशक भावना संकेतकों के लिए ग्रे मार्केट प्रीमियम की निगरानी की जा रही है।"], "framing": {"center": ["Reports focus on the opening of four IPOs for subscription.", "Highlights varying levels of investor interest, with some IPOs seeing higher demand than others.", "Mentions specific companies like Sunshine Pictures, Lalithaa Jewellery Mart, Shankesh Jewellers, and Horizon Industrial Parks.", "Notes the observation of grey market premiums (GMP) as an indicator of investor sentiment."]}, "framing_hi": {"center": ["रिपोर्टें सब्सक्रिप्शन के लिए चार आईपीओ के खुलने पर केंद्रित हैं।", "कुछ आईपीओ की मांग दूसरों की तुलना में अधिक होने के साथ, निवेशकों की रुचि के विभिन्न स्तरों पर प्रकाश डालता है।", "सनशाइन पिक्चर्स, ललिथा ज्वेलरी मार्ट, शंकेश ज्वेलर्स और होराइजन इंडस्ट्रियल पार्क्स जैसी विशिष्ट कंपनियों का उल्लेख करता है।", "निवेशक भावना के संकेतक के रूप में ग्रे मार्केट प्रीमियम (जीएमपी) के अवलोकन को नोट करता है।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "https://bsmedia.business-standard.com/_media/bs/img/article/2025-03/21/thumb/fitandfill/1200X628/1742522388-452.jpg", "sources": [{"source": "Business Standard", "owner": "Business Standard", "lean": "center", "language": "en", "url": "https://www.business-standard.com/markets/ipo/shankesh-jewellers-ipo-gmp-at-2-offer-opens-today-can-it-add-shine-to-your-portfolio-126081800143_1.html", "headline": "Shankesh Jewellers IPO opens today : Can it add shine to your portfolio ?"}, {"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/market/ipo/ipo-gmps-lalitha-jewellery-ipo-gmp-vs-horizon-industrial-parks-ipo-gmp-vs-sunshine-pictures-ipo-gmp-11787036925581.html", "headline": "IPO GMPs: Lalitha Jewellery IPO, Horizon Industrial Parks IPO to Shankesh Jewellers IPO —what grey market premium hints"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Business Standard", "Mint"], "owners": ["Business Standard", "HT Media"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://bsmedia.business-standard.com/_media/bs/img/article/2025-03/21/thumb/fitandfill/1200X628/1742522388-452.jpg', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.758225'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15941, 'Himachal Pradesh to reduce IAS, IFS, IPS officer numbers', 'हिमाचल प्रदेश में आईएएस, आईएफएस, आईपीएस अधिकारियों की संख्या घटाई जाएगी', 'Himachal Pradesh plans to reduce the number of Indian Administrative Service (IAS), Indian Forest Service (IFS), and Indian Police Service (IPS) officers in the state. The Chief Minister stated that officers are sitting idle and their talent is being wasted. Currently, over 20 IAS officers and more than a dozen IPS and IFS officers are on deputation in the state.', 'हिमाचल प्रदेश सरकार राज्य में भारतीय प्रशासनिक सेवा (आईएएस), भारतीय वन सेवा (आईएफएस) और भारतीय पुलिस सेवा (आईपीएस) के अधिकारियों की संख्या कम करने की योजना बना रही है। मुख्यमंत्री ने कहा कि अधिकारी निष्क्रिय बैठे हैं और उनकी प्रतिभा बर्बाद हो रही है। वर्तमान में, 20 से अधिक आईएएस अधिकारी और एक दर्जन से अधिक आईपीएस और आईएफएस अधिकारी राज्य में प्रतिनियुक्ति पर हैं।', '["Himachal Pradesh government plans to reduce the strength of IAS, IFS, and IPS officers.", "The move aims to curb bureaucratic costs.", "The Chief Minister cited that officers are sitting idle and their talent is being wasted.", "Over 20 IAS officers and more than a dozen IPS and IFS officers are currently on deputation in Himachal Pradesh."]'::jsonb, '["हिमाचल प्रदेश सरकार आईएएस, आईएफएस और आईपीएस अधिकारियों की संख्या कम करने की योजना बना रही है।", "इस कदम का उद्देश्य नौकरशाही लागत को कम करना है।", "मुख्यमंत्री ने कहा कि अधिकारी निष्क्रिय बैठे हैं और उनकी प्रतिभा बर्बाद हो रही है।", "वर्तमान में, 20 से अधिक आईएएस अधिकारी और एक दर्जन से अधिक आईपीएस और आईएफएस अधिकारी हिमाचल प्रदेश में प्रतिनियुक्ति पर हैं।"]'::jsonb, 'Politics', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["NDTV"], "owners": ["NDTV"]}, "right": {"count": 1, "sources": ["India Today"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "India Today", "owner": "India Today Group", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMibEFVX3lxTE1MZmFOOE05amZKMnA4d1luNHJMMXJyZklUYTFEVDZoa2Z5YnFjZnBGdzQtZDNSYVZsakczRXNjTUxfMEk5UXhHNHRBZlNUSFZwU3lGMnp2YVMxQm8yVHhOR1dQLW84Vk5XQ2N1YQ?oc=5", "headline": "Officers sitting idle, talent being wasted: Himachal CM plans big bureaucracy cut"}, {"source": "NDTV", "owner": "NDTV", "lean": "center", "language": "en", "url": "https://www.ndtv.com/india-news/himachal-pradesh-plans-to-reduce-ias-ifs-ips-officers-to-curb-bureaucratic-costs-11925286", "headline": "Himachal Plans To Reduce IAS, IFS, IPS Officers To Curb Bureaucratic Costs"}]'::jsonb, '{"title": "Himachal Pradesh to reduce IAS, IFS, IPS officer numbers", "summary": "Himachal Pradesh plans to reduce the number of Indian Administrative Service (IAS), Indian Forest Service (IFS), and Indian Police Service (IPS) officers in the state. The Chief Minister stated that officers are sitting idle and their talent is being wasted. Currently, over 20 IAS officers and more than a dozen IPS and IFS officers are on deputation in the state.", "summary_points": ["Himachal Pradesh government plans to reduce the strength of IAS, IFS, and IPS officers.", "The move aims to curb bureaucratic costs.", "The Chief Minister cited that officers are sitting idle and their talent is being wasted.", "Over 20 IAS officers and more than a dozen IPS and IFS officers are currently on deputation in Himachal Pradesh."], "title_hi": "हिमाचल प्रदेश में आईएएस, आईएफएस, आईपीएस अधिकारियों की संख्या घटाई जाएगी", "summary_hi": "हिमाचल प्रदेश सरकार राज्य में भारतीय प्रशासनिक सेवा (आईएएस), भारतीय वन सेवा (आईएफएस) और भारतीय पुलिस सेवा (आईपीएस) के अधिकारियों की संख्या कम करने की योजना बना रही है। मुख्यमंत्री ने कहा कि अधिकारी निष्क्रिय बैठे हैं और उनकी प्रतिभा बर्बाद हो रही है। वर्तमान में, 20 से अधिक आईएएस अधिकारी और एक दर्जन से अधिक आईपीएस और आईएफएस अधिकारी राज्य में प्रतिनियुक्ति पर हैं।", "summary_points_hi": ["हिमाचल प्रदेश सरकार आईएएस, आईएफएस और आईपीएस अधिकारियों की संख्या कम करने की योजना बना रही है।", "इस कदम का उद्देश्य नौकरशाही लागत को कम करना है।", "मुख्यमंत्री ने कहा कि अधिकारी निष्क्रिय बैठे हैं और उनकी प्रतिभा बर्बाद हो रही है।", "वर्तमान में, 20 से अधिक आईएएस अधिकारी और एक दर्जन से अधिक आईपीएस और आईएफएस अधिकारी हिमाचल प्रदेश में प्रतिनियुक्ति पर हैं।"], "framing": {}, "framing_hi": {}, "topic": "Politics", "region": "India", "published_at": null, "image_url": "https://c.ndtvimg.com/2026-04/i0ipf00s_sukhvinder-singh-sukhu_625x300_25_April_26.jpg?im=FitAndFill,algorithm=dnn,width=1280,height=720", "sources": [{"source": "India Today", "owner": "India Today Group", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMibEFVX3lxTE1MZmFOOE05amZKMnA4d1luNHJMMXJyZklUYTFEVDZoa2Z5YnFjZnBGdzQtZDNSYVZsakczRXNjTUxfMEk5UXhHNHRBZlNUSFZwU3lGMnp2YVMxQm8yVHhOR1dQLW84Vk5XQ2N1YQ?oc=5", "headline": "Officers sitting idle, talent being wasted: Himachal CM plans big bureaucracy cut"}, {"source": "NDTV", "owner": "NDTV", "lean": "center", "language": "en", "url": "https://www.ndtv.com/india-news/himachal-pradesh-plans-to-reduce-ias-ifs-ips-officers-to-curb-bureaucratic-costs-11925286", "headline": "Himachal Plans To Reduce IAS, IFS, IPS Officers To Curb Bureaucratic Costs"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["NDTV"], "owners": ["NDTV"]}, "right": {"count": 1, "sources": ["India Today"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://c.ndtvimg.com/2026-04/i0ipf00s_sukhvinder-singh-sukhu_625x300_25_April_26.jpg?im=FitAndFill,algorithm=dnn,width=1280,height=720', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.734196'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15940, 'LeT operative claims Hafiz Saeed sent 10,000 militants to Kashmir', 'लश्कर-ए-तैयबा के गुर्गे का दावा: हाफिज सईद ने कश्मीर भेजे थे 10 हजार आतंकी', 'A Lashkar-e-Taiba (LeT) operative, Maulana Moulvi Naseer Madani, claimed during a public gathering in Bahawalpur, Pakistan, that Hafiz Saeed had dispatched 10,000 militants to Kashmir for ''sacrifice''. Madani stated that Saeed is now facing punishment for this action. The operative''s remarks were made at a rally for LeT''s political wing. The claim suggests a significant infiltration attempt into the region.', 'लश्कर-ए-तैयबा (LeT) के एक गुर्गे, मौलाना मौलवी नसीर मदनी ने पाकिस्तान के बहावलपुर में एक सार्वजनिक सभा के दौरान दावा किया कि हाफिज सईद ने ''कुर्बानी'' के लिए 10,000 आतंकवादियों को कश्मीर भेजा था। मदनी ने कहा कि सईद को अब इस कार्रवाई की सजा मिल रही है। यह दावा LeT के राजनीतिक विंग के एक जलसे में किया गया था। इस दावे से क्षेत्र में एक महत्वपूर्ण घुसपैठ के प्रयास का संकेत मिलता है।', '["Lashkar-e-Taiba operative Maulana Moulvi Naseer Madani made the claim.", "Madani stated Hafiz Saeed sent 10,000 militants to Kashmir.", "The operative said the militants were sent for ''sacrifice''.", "Madani made these statements at a public gathering in Bahawalpur, Pakistan.", "The event was for LeT''s political wing."]'::jsonb, '["लश्कर-ए-तैयबा के गुर्गे मौलाना मौलवी नसीर मदनी ने यह दावा किया।", "मदनी ने कहा कि हाफिज सईद ने 10,000 आतंकवादियों को कश्मीर भेजा था।", "गुर्गे ने कहा कि आतंकवादियों को ''कुर्बानी'' के लिए भेजा गया था।", "मदनी ने ये बयान पाकिस्तान के बहावलपुर में एक सार्वजनिक सभा में दिए।", "यह कार्यक्रम LeT के राजनीतिक विंग के लिए था।"]'::jsonb, 'Crime & Law', 'World', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Amar Ujala"], "owners": ["Amar Ujala"]}, "right": {"count": 1, "sources": ["Aaj Tak"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Aaj Tak", "owner": "India Today Group", "lean": "right", "language": "hi", "url": "https://www.aajtak.in/world/story/maulana-nasir-madni-reveals-hafiz-saeed-send-thousands-children-kashmir-terrorism-ntc-ntyv-rpti-2624621-2026-08-18", "headline": "''हाफिज सईद ने कश्मीर भेजे 10 हजार आतंकी'', मौलाना ने बताई सच्चाई"}, {"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/world/let-s-naseer-madani-claimed-that-hafiz-saeed-sent-10-000-militants-to-kashmir-terrorist-group-let-2026-08-18", "headline": "घाटी में अशांति फैलाने की ना''पाक'' साजिश: हाफिज सईद के गुर्गे का दावा-LeT ने 10 हजार आतंकियों को भेजा था कश्मीर"}]'::jsonb, '{"title": "LeT operative claims Hafiz Saeed sent 10,000 militants to Kashmir", "summary": "A Lashkar-e-Taiba (LeT) operative, Maulana Moulvi Naseer Madani, claimed during a public gathering in Bahawalpur, Pakistan, that Hafiz Saeed had dispatched 10,000 militants to Kashmir for ''sacrifice''. Madani stated that Saeed is now facing punishment for this action. The operative''s remarks were made at a rally for LeT''s political wing. The claim suggests a significant infiltration attempt into the region.", "summary_points": ["Lashkar-e-Taiba operative Maulana Moulvi Naseer Madani made the claim.", "Madani stated Hafiz Saeed sent 10,000 militants to Kashmir.", "The operative said the militants were sent for ''sacrifice''.", "Madani made these statements at a public gathering in Bahawalpur, Pakistan.", "The event was for LeT''s political wing."], "title_hi": "लश्कर-ए-तैयबा के गुर्गे का दावा: हाफिज सईद ने कश्मीर भेजे थे 10 हजार आतंकी", "summary_hi": "लश्कर-ए-तैयबा (LeT) के एक गुर्गे, मौलाना मौलवी नसीर मदनी ने पाकिस्तान के बहावलपुर में एक सार्वजनिक सभा के दौरान दावा किया कि हाफिज सईद ने ''कुर्बानी'' के लिए 10,000 आतंकवादियों को कश्मीर भेजा था। मदनी ने कहा कि सईद को अब इस कार्रवाई की सजा मिल रही है। यह दावा LeT के राजनीतिक विंग के एक जलसे में किया गया था। इस दावे से क्षेत्र में एक महत्वपूर्ण घुसपैठ के प्रयास का संकेत मिलता है।", "summary_points_hi": ["लश्कर-ए-तैयबा के गुर्गे मौलाना मौलवी नसीर मदनी ने यह दावा किया।", "मदनी ने कहा कि हाफिज सईद ने 10,000 आतंकवादियों को कश्मीर भेजा था।", "गुर्गे ने कहा कि आतंकवादियों को ''कुर्बानी'' के लिए भेजा गया था।", "मदनी ने ये बयान पाकिस्तान के बहावलपुर में एक सार्वजनिक सभा में दिए।", "यह कार्यक्रम LeT के राजनीतिक विंग के लिए था।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "World", "published_at": null, "image_url": "", "sources": [{"source": "Aaj Tak", "owner": "India Today Group", "lean": "right", "language": "hi", "url": "https://www.aajtak.in/world/story/maulana-nasir-madni-reveals-hafiz-saeed-send-thousands-children-kashmir-terrorism-ntc-ntyv-rpti-2624621-2026-08-18", "headline": "''हाफिज सईद ने कश्मीर भेजे 10 हजार आतंकी'', मौलाना ने बताई सच्चाई"}, {"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/world/let-s-naseer-madani-claimed-that-hafiz-saeed-sent-10-000-militants-to-kashmir-terrorist-group-let-2026-08-18", "headline": "घाटी में अशांति फैलाने की ना''पाक'' साजिश: हाफिज सईद के गुर्गे का दावा-LeT ने 10 हजार आतंकियों को भेजा था कश्मीर"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Amar Ujala"], "owners": ["Amar Ujala"]}, "right": {"count": 1, "sources": ["Aaj Tak"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.709389'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15939, 'New BJP Mahila Morcha Chief''s Political Journey Highlighted', 'भाजपा महिला मोर्चा की नई राष्ट्रीय अध्यक्ष की राजनीतिक यात्रा पर प्रकाश', 'The political career of Roop Kumari Chaudhary, the newly appointed national president of the BJP Mahila Morcha, is being detailed. Her journey began as a Zila Panchayat member and has now led her to a national leadership role. Coverage notes her educational background, having studied up to the 10th grade, and highlights her transition from local politics to a significant national position within the party. Her path to becoming a Member of Parliament is also mentioned in relation to her rise.', 'भाजपा महिला मोर्चा की नवनियुक्त राष्ट्रीय अध्यक्ष रूप कुमारी चौधरी के राजनीतिक करियर का विवरण दिया जा रहा है। उनकी यात्रा जिला पंचायत सदस्य के रूप में शुरू हुई और अब वह राष्ट्रीय नेतृत्व की भूमिका में आ गई हैं। कवरेज में उनकी शैक्षिक पृष्ठभूमि का उल्लेख है, जिन्होंने 10वीं कक्षा तक पढ़ाई की है, और पार्टी के भीतर एक महत्वपूर्ण राष्ट्रीय पद पर उनके परिवर्तन पर प्रकाश डाला गया है। सांसद बनने तक के उनके सफर का भी उनके उदय के संबंध में उल्लेख किया गया है।', '["Roop Kumari Chaudhary has been appointed the national president of the BJP Mahila Morcha.", "Her political career started as a Zila Panchayat member.", "She has also become a Member of Parliament.", "Her educational qualification is up to the 10th grade.", "The coverage details her political journey and rise within the party."]'::jsonb, '["रूप कुमारी चौधरी को भाजपा महिला मोर्चा का राष्ट्रीय अध्यक्ष नियुक्त किया गया है।", "उनका राजनीतिक करियर जिला पंचायत सदस्य के रूप में शुरू हुआ।", "वह सांसद भी बन चुकी हैं।", "उनकी शैक्षिक योग्यता 10वीं कक्षा तक है।", "कवरेज में उनकी राजनीतिक यात्रा और पार्टी के भीतर उनके उदय का विवरण दिया गया है।"]'::jsonb, 'Politics', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Amar Ujala", "Patrika"], "owners": ["Amar Ujala", "Patrika"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Highlighted the political journey of Roop Kumari Chaudhary from Zila Panchayat member to national president of BJP Mahila Morcha.", "Mentioned her educational background, studying up to the 10th grade.", "Detailed her political career, including her path to becoming a Member of Parliament."]}'::jsonb, '{"center": ["भाजपा महिला मोर्चा की राष्ट्रीय अध्यक्ष रूप कुमारी चौधरी की जिला पंचायत सदस्य से राष्ट्रीय अध्यक्ष बनने तक की राजनीतिक यात्रा को उजागर किया गया।", "उनकी शैक्षिक पृष्ठभूमि का उल्लेख किया गया, जिन्होंने 10वीं कक्षा तक पढ़ाई की है।", "सांसद बनने सहित उनके राजनीतिक करियर का विवरण दिया गया।"]}'::jsonb, '[{"source": "Patrika", "owner": "Patrika", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "जिला पंचायत सदस्य से राष्ट्रीय अध्यक्ष बनने का सफर, महासमुंद की रूप कुमारी 10वीं तक की है पढ़ाई, ऐसा है राजनीति करियर"}, {"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/india-news/who-is-roop-kumari-choudhary-from-zila-panchayat-member-to-bjp-mahila-morcha-chief-in-19-years-2026-08-18", "headline": "कौन हैं रूप कुमारी चौधरी: 19 साल में जिला पंचायत से सांसद तक का सफर, कैसे मिली भाजपा महिला मोर्चा की कमान?"}]'::jsonb, '{"title": "New BJP Mahila Morcha Chief''s Political Journey Highlighted", "summary": "The political career of Roop Kumari Chaudhary, the newly appointed national president of the BJP Mahila Morcha, is being detail